using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.AddressableAssets;using LighFight.Runtime;
public sealed class EmbeddedContentPlayerProbe:MonoBehaviour {
 public ContentBootstrap bootstrap;public string output;readonly List<string> rows=new List<string>();TracingProvider provider;float started;string cache;bool completed;int httpAttempts,errors;
 void Awake(){Application.runInBackground=true;Application.logMessageReceived+=OnLog;started=Time.realtimeSinceStartup;Directory.CreateDirectory(output);cache=Path.Combine(Application.persistentDataPath,"lighfight-manifest.json");File.WriteAllText(cache,"embedded QA sentinel; remote cache must not change");Addressables.WebRequestOverride=request=>{if(request.url.StartsWith("http",StringComparison.OrdinalIgnoreCase)){httpAttempts++;throw new IOException("Network disabled by QA transport gate");}};}
 void Start(){StartCoroutine(Guard(Run()));}
 void Update(){if(!completed&&Time.realtimeSinceStartup-started>600)Finish(false,"timeout");}
 IEnumerator Guard(IEnumerator first){var stack=new Stack<IEnumerator>();stack.Push(first);while(stack.Count>0){bool moved;object item=null;try{moved=stack.Peek().MoveNext();if(moved)item=stack.Peek().Current;}catch(Exception e){Finish(false,e.ToString());yield break;}if(!moved){stack.Pop();continue;}if(item is IEnumerator nested)stack.Push(nested);else yield return item;}}
 IEnumerator Run(){while(!bootstrap.IsPlaying){if(bootstrap.ErrorCode!=null)throw new Exception(bootstrap.ErrorCode);yield return null;}var catalog=bootstrap.OpenedContent;if(!catalog.streamed||catalog.fighters.Length!=0||catalog.arenas.Length!=0)throw new Exception("Inline startup dependencies");var game=FindFirstObjectByType<Prototype>();yield return null;while(game.ActorsLoading)yield return null;if(catalog.FighterCount>2&&Resources.FindObjectsOfTypeAll<FighterView>().Count(v=>!v.gameObject.scene.IsValid())>=catalog.FighterCount)throw new Exception("Unselected bodies loaded at startup");Snapshot("initial-real-roster");yield return new WaitForEndOfFrame();Capture("initial-roster");
  provider=new TracingProvider(rows);game.SelectedAssetProvider=provider;
  foreach(int fighter in Enumerable.Range(0,catalog.FighterCount).Reverse()){
   typeof(Prototype).GetField("selectedArena",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(game,fighter%catalog.ArenaCount);game.SelectRosterFighter(fighter);while(game.ActorsLoading)yield return null;var lease=(SelectedContentLease)typeof(Prototype).GetField("selectedContentLease",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(game);if(lease==null||!lease.ValidateSelected(out var error))throw new Exception("Real selected lease invalid");yield return Resources.UnloadUnusedAssets();Snapshot("selected-"+fighter);yield return new WaitForEndOfFrame();Capture("selected-"+fighter);
  }
  Destroy(bootstrap.gameObject);yield return null;yield return null;yield return null;yield return Resources.UnloadUnusedAssets();Snapshot("released");if(AssetBundle.GetAllLoadedAssetBundles().Any())throw new Exception("Asset bundles remain resident after release");if(provider.Active!=0)throw new Exception("Unreleased selected handles: "+provider.Active);if(httpAttempts!=0)throw new Exception("Network attempt");if(File.ReadAllText(cache)!="embedded QA sentinel; remote cache must not change")throw new Exception("Embedded mode overwrote remote cache");Finish(true,"");
 }
 void Snapshot(string phase){var bodies=Resources.FindObjectsOfTypeAll<FighterView>().Where(v=>!v.gameObject.scene.IsValid()).Select(v=>v.name).Distinct();var arenas=Resources.FindObjectsOfTypeAll<OfficeArena>().Where(v=>!v.gameObject.scene.IsValid()).Select(v=>v.name).Distinct();rows.Add(phase+",residency,"+(provider?.Active??0)+",\""+string.Join("|",bodies)+"\",\""+string.Join("|",arenas)+"\",bundles="+AssetBundle.GetAllLoadedAssetBundles().Count());}
 void Capture(string name){var t=new Texture2D(Screen.width,Screen.height,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,Screen.width,Screen.height),0,0);t.Apply();File.WriteAllBytes(Path.Combine(output,name+".rgba"),t.GetRawTextureData<byte>().ToArray());File.WriteAllText(Path.Combine(output,name+".size"),Screen.width+","+Screen.height);Destroy(t);}
 void OnLog(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception)errors++;}
 void Finish(bool ok,string error){if(completed)return;if(ok&&errors>0){ok=false;error="Unexpected production runtime errors="+errors;}completed=true;File.WriteAllLines(Path.Combine(output,"real-resources.csv"),new[]{"phase,event,activeHandles,bodies,arenas,detail"}.Concat(rows));File.WriteAllText(Path.Combine(output,"result.json"),JsonUtility.ToJson(new Result{passed=ok,error=error,httpAttempts=httpAttempts,errors=errors,remoteCacheUnchanged=File.Exists(cache)&&File.ReadAllText(cache)=="embedded QA sentinel; remote cache must not change",loads=provider?.Loads??0,releases=provider?.Releases??0},true));Debug.Log("AGENT_RESULT embedded player "+(ok?"PASS":"FAIL "+error));Addressables.WebRequestOverride=null;Application.Quit(ok?0:1);}
 [Serializable]class Result{public bool passed,remoteCacheUnchanged;public string error;public int httpAttempts,errors,loads,releases;}
 sealed class TracingProvider:ISelectedAssetProvider {
  readonly AddressableSelectedAssetProvider real=new AddressableSelectedAssetProvider();readonly List<string> rows;public int Loads,Releases;public int Active=>Loads-Releases;public TracingProvider(List<string> log){rows=log;}public ISelectedAssetLoad Load(string key){var inner=real.Load(key);Loads++;rows.Add(Time.frameCount+",real-Addressables-load,"+Active+",\""+key+"\"");return new Traced(inner,this,key);}
  sealed class Traced:ISelectedAssetLoad{readonly ISelectedAssetLoad inner;readonly TracingProvider owner;readonly string key;bool disposed;public Traced(ISelectedAssetLoad value,TracingProvider p,string k){inner=value;owner=p;key=k;}public bool IsDone=>inner.IsDone;public GameObject Asset=>inner.Asset;public string Error=>inner.Error;public void Dispose(){if(disposed)return;disposed=true;inner.Dispose();owner.Releases++;owner.rows.Add(Time.frameCount+",real-Addressables-release,"+owner.Active+",\""+key+"\",,"+inner.Error);}}
 }
}
